"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1344],{61344:e=>{e.exports=JSON.parse('[{"question":"Which tech had the most callbacks last month?","answer":"Tyler Brooks had the highest callback rate last month at 14% (3 callbacks out of 21 completed jobs). The average across the team is 8%. His callbacks were concentrated on refrigerant recharge jobs — a pattern that suggests possible leak detection misses during diagnosis. Recommending a targeted review of his leak-check procedure.","chart":{"type":"bar","title":"Callback rate by technician (June)","data":[{"name":"Dev P.","rate":2},{"name":"Marcus W.","rate":6},{"name":"Sofia G.","rate":9},{"name":"James C.","rate":4},{"name":"Aisha J.","rate":12},{"name":"Tyler B.","rate":14},{"name":"Priya N.","rate":5},{"name":"Carlos R.","rate":8}],"xKey":"name","yKey":"rate","dataKey":"rate"},"notFound":false,"confidence":0.95},{"question":"What\'s our busiest day of the week?","answer":"Monday is consistently your busiest day, averaging 18.4 jobs per week over the last 90 days. This is likely driven by weekend equipment failures that customers delay calling about until Monday. Tuesday is the second busiest at 16.2 jobs. Saturday is the quietest at 6.8 jobs — consider whether reduced Saturday staffing aligns with that lower volume.","chart":{"type":"bar","title":"Average jobs by day of week (last 90 days)","data":[{"day":"Mon","jobs":18.4},{"day":"Tue","jobs":16.2},{"day":"Wed","jobs":14.8},{"day":"Thu","jobs":15.1},{"day":"Fri","jobs":13.6},{"day":"Sat","jobs":6.8}],"xKey":"day","yKey":"jobs","dataKey":"jobs"},"notFound":false,"confidence":0.97},{"question":"How much revenue did maintenance plans generate this quarter?","answer":"Maintenance plans generated $7,320 in recurring revenue this quarter across 122 active members. Comfort Club members also converted to repairs at a 34% higher rate than non-members, contributing an estimated additional $18,400 in repair revenue. Total plan-attributable revenue this quarter: approximately $25,720.","chart":{"type":"bar","title":"Maintenance plan revenue by tier (Q2)","data":[{"tier":"Basic ($12.99)","revenue":1920},{"tier":"Comfort ($19.99)","revenue":3480},{"tier":"Premier ($29.99)","revenue":1920}],"xKey":"tier","yKey":"revenue","dataKey":"revenue"},"notFound":false,"confidence":0.93},{"question":"What\'s the average ticket value by job type?","answer":"Installs have the highest average ticket at $11,240, driven by full system replacements. Repairs average $462, maintenance $129, and estimates $0 (they convert to repair/install jobs). Your repair average has increased 12% year-over-year, which correlates with aging equipment in your service area — units installed 2008–2012 are hitting replacement age.","chart":{"type":"bar","title":"Average ticket by job type","data":[{"type":"Install","avg":11240},{"type":"Repair","avg":462},{"type":"Maintenance","avg":129},{"type":"Estimate","avg":0}],"xKey":"type","yKey":"avg","dataKey":"avg"},"notFound":false,"confidence":0.94},{"question":"Which customers are most overdue for a visit?","answer":"28 Comfort Club members haven\'t had a service visit in over 14 months. The top 5 by lifetime value are: Patricia Chen ($4,200 LTV, last visit 16 months ago), Robert Kim ($3,800, 18 months), David Torres ($3,400, 15 months), Jennifer Walsh ($3,100, 17 months), and Marcus Johnson ($2,900, 14 months). Recommend Echo send a re-engagement message to all 28 this week.","chart":{"type":"bar","title":"Members overdue for visit (months since last service)","data":[{"name":"P. Chen","months":16},{"name":"R. Kim","months":18},{"name":"D. Torres","months":15},{"name":"J. Walsh","months":17},{"name":"M. Johnson","months":14}],"xKey":"name","yKey":"months","dataKey":"months"},"notFound":false,"confidence":0.96},{"question":"How many jobs did Ava book vs web this month?","answer":"This month Ava booked 187 jobs (64% of total bookings), the website form accounted for 58 jobs (20%), phone-to-human 31 jobs (11%), and membership auto-scheduling 14 jobs (5%). Ava\'s booking rate has grown from 48% to 64% over the last 6 months as customers learn to trust the AI receptionist.","chart":{"type":"pie","title":"Job sources this month","data":[{"name":"Ava (AI call)","value":187},{"name":"Web form","value":58},{"name":"Human phone","value":31},{"name":"Membership auto","value":14}],"dataKey":"value"},"notFound":false,"confidence":0.98},{"question":"What\'s our first-time fix rate trend?","answer":"Your fleet-wide first-time fix rate is 91.4% this quarter, up from 88.2% in Q1. The improvement correlates with Lens adoption — jobs where the tech used photo diagnosis before building an estimate show a 94.8% first-time fix rate vs. 88.1% for jobs without it. Lens is already preventing callbacks.","chart":{"type":"line","title":"First-time fix rate by month","data":[{"month":"Feb","rate":87.4},{"month":"Mar","rate":88.2},{"month":"Apr","rate":89.1},{"month":"May","rate":90.3},{"month":"Jun","rate":91},{"month":"Jul","rate":91.4}],"xKey":"month","yKey":"rate","dataKey":"rate"},"notFound":false,"confidence":0.94},{"question":"Which equipment brands break down most often?","answer":"Goodman units account for 31% of repair visits despite representing only 22% of your installed base — a disproportionate breakdown rate. Carrier units have the lowest repair frequency at 14% of visits vs. 18% of the installed base. Rheem and Trane are close to their base rate. When presenting replacement options, Goodman-to-Carrier upgrades have the highest customer satisfaction in your data.","chart":{"type":"bar","title":"Repair visit share vs. installed base share","data":[{"brand":"Goodman","repairs":31,"installed":22},{"brand":"Carrier","repairs":14,"installed":18},{"brand":"Trane","repairs":19,"installed":20},{"brand":"Rheem","repairs":18,"installed":17},{"brand":"Lennox","repairs":12,"installed":13},{"brand":"Other","repairs":6,"installed":10}],"xKey":"brand","yKey":"repairs","dataKey":"repairs"},"notFound":false,"confidence":0.91}]')}}]);